for w,g,b in [('quai','Названа платформа отправления.','Время прибытия и тип билета не сообщают нужную платформу.'),('y-lieu','Короткая замена отсылает к названной платформе.','Выбор билета и бронирование номера относятся к предметам, а здесь нужно вернуться к месту.'),('correspondance','Названа пересадка в полдень.','Прямой поезд обозначает отсутствие пересадки, билет в одну сторону — направление, а не пересадку.'),('direct','Выбран прямой поезд без пересадки.','Пересадка меняет условие, платформа отправления сама по себе не говорит об отсутствии пересадки.'),('changer','Запрошено изменение имеющегося билета на нужный поезд.','Покупка нового билета и выбор варианта — другие действия. Здесь требуется попросить изменить имеющийся билет.'),('retard','Названа задержка на двадцать минут.','Номер платформы и час прибытия — другие сведения. Нужны задержка и её длительность.'),('minute','Названы двадцать минут задержки.','Час — другая единица, номер платформы не является длительностью.')]:W[w]['review_items'][1]['feedback']=fb(g,b)

